_oil":"","rear_shock_piston":"","rear_spring":"","rear_shock_upper_position":"","rear_shock_lower_position":"","rear_shock_length":"","front_tire":"","front_insert":"","front_wheel_hex_offset":"","rear_tire":"","rear_insert":"","rear_wheel_hex_offset":"","front_arb":"","rear_arb":"","pinion":"","spur":"","final_drive":"","motor_setting":"","esc_setting":"","battery_placement":"","weight_placement":"","total_weight":"","front_diff_configuration":"","front_diff_oil":"","rear_diff_configuration":"","rear_diff_oil":"","belt_tension":"","tire_additive":"","additive_time":"","tire_preparation":"","wing_position":"","wing_angle":""}}},"notes":null}]$payload$::jsonb) loop
   perform public.change_active_race_class(payload->>'race_class');
   insert into public.race_setups (user_id,setup_type,setup_name,track_name,race_date,race_class,cross_weight,toe,toe_direction,front_ride_height,rear_ride_height,stagger,rf_pressure,rf_shock,rf_spring,rf_caster,rf_camber,rf_wheel_offset,rf_cw_turns,lf_pressure,lf_shock,lf_spring,lf_caster,lf_camber,lf_wheel_offset,lf_cw_turns,lr_tire_size,lr_pressure,lr_shock,lr_spring,lr_wheel_offset,lr_cw_turns,rr_tire_size,rr_pressure,rr_shock,rr_spring,rr_wheel_offset,rr_cw_turns,lr_trailing_arm,rr_trailing_arm,third_link,panhard_bar,gear_ratio,custom_fields,notes)
   select r.user_id,r.setup_type,r.setup_name,r.track_name,r.race_date,r.race_class,r.cross_weight,r.toe,r.toe_direction,r.front_ride_height,r.rear_ride_height,r.stagger,r.rf_pressure,r.rf_shock,r.rf_spring,r.rf_caster,r.rf_camber,r.rf_wheel_offset,r.rf_cw_turns,r.lf_pressure,r.lf_shock,r.lf_spring,r.lf_caster,r.lf_camber,r.lf_wheel_offset,r.lf_cw_turns,r.lr_tire_size,r.lr_pressure,r.lr_shock,r.lr_spring,r.lr_wheel_offset,r.lr_cw_turns,r.rr_tire_size,r.rr_pressure,r.rr_shock,r.rr_spring,r.rr_wheel_offset,r.rr_cw_turns,r.lr_trailing_arm,r.rr_trailing_arm,r.third_link,r.panhard_bar,r.gear_ratio,r.custom_fields,r.notes from jsonb_populate_record(null::public.race_setups,payload) r returning id into setup_id;
   select custom_fields into actual from public.race_setups where id=setup_id;
   if actual is distinct from payload->'custom_fields' then raise exception 'Reopen mismatch for %',payload->>'race_class'; end if;
   if payload->>'race_class'='GT3' then original_gt3:=setup_id; expected:=actual; end if;
 end loop;
 update public.race_setups set setup_name='LIVE QA - GT3 - RENAMED - 20261001' where id=original_gt3;
 if not exists(select 1 from public.race_setups where id=original_gt3 and setup_name='LIVE QA - GT3 - RENAMED - 20261001' and custom_fields=expected) then raise exception 'Rename/reopen failed'; end if;
 perform public.change_active_race_class('GT3');
 insert into public.race_setups (user_id,setup_type,setup_name,track_name,race_date,race_class,cross_weight,toe,toe_direction,front_ride_height,rear_ride_height,stagger,rf_pressure,rf_shock,rf_spring,rf_caster,rf_camber,rf_wheel_offset,rf_cw_turns,lf_pressure,lf_shock,lf_spring,lf_caster,lf_camber,lf_wheel_offset,lf_cw_turns,lr_tire_size,lr_pressure,lr_shock,lr_spring,lr_wheel_offset,lr_cw_turns,rr_tire_size,rr_pressure,rr_shock,rr_spring,rr_wheel_offset,rr_cw_turns,lr_trailing_arm,rr_trailing_arm,third_link,panhard_bar,gear_ratio,custom_fields,notes)
 select r.user_id,r.setup_type,'LIVE QA - GT3 - COPY - 20261001',r.track_name,r.race_date,r.race_class,r.cross_weight,r.toe,r.toe_direction,r.front_ride_height,r.rear_ride_height,r.stagger,r.rf_pressure,r.rf_shock,r.rf_spring,r.rf_caster,r.rf_camber,r.rf_wheel_offset,r.rf_cw_turns,r.lf_pressure,r.lf_shock,r.lf_spring,r.lf_caster,r.lf_camber,r.lf_wheel_offset,r.lf_cw_turns,r.lr_tire_size,r.lr_pressure,r.lr_shock,r.lr_spring,r.lr_wheel_offset,r.lr_cw_turns,r.rr_tire_size,r.rr_pressure,r.rr_shock,r.rr_spring,r.rr_wheel_offset,r.rr_cw_turns,r.lr_trailing_arm,r.rr_trailing_arm,r.third_link,r.panhard_bar,r.gear_ratio,r.custom_fields,r.notes from public.race_setups r where r.id=original_gt3 returning id into copied_gt3;
 select custom_fields into actual from public.race_setups where id=copied_gt3;
 if actual is distinct from expected then raise exception 'Copy mismatch'; end if;
 update public.race_setups set custom_fields=jsonb_set(custom_fields,'{onlyfast_setup_library_v1,values,ambient_temperature}','"90.0"'::jsonb) where id=copied_gt3;
 if not exists(select 1 from public.race_setups where id=copied_gt3 and custom_fields#>>'{onlyfast_setup_library_v1,values,ambient_temperature}'='90.0') then raise exception 'Copy edit/reopen failed'; end if;
 select custom_fields into actual from public.race_setups where id=original_gt3;
 if actual is distinct from expected then raise exception 'Original changed when editing copy'; end if;
 perform public.change_active_race_class(original_class);
 select coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]'::jsonb) into restored_rows from public.race_setups r where r.id in (select (value->>'id')::uuid from jsonb_array_elements(original_rows));
 if original_rows is distinct from restored_rows then raise exception 'Pre-existing setup data changed'; end if;
 if public.get_active_race_class_state()->>'active_class' is distinct from original_class then raise exception 'Original class was not restored'; end if;
 insert into onlyfast_live_qa_result values(jsonb_build_object('existing_setups_unchanged',jsonb_array_length(original_rows),
   'active_class_restored',original_class,'gt3_original_id',original_gt3,'gt3_copy_id',copied_gt3,
   'rename_copy_edit_original_unchanged',true,'repeated_class_switches',7,'new_qa_setups',6));
end;
$checks$;
select report || jsonb_build_object('saved_rows',(select jsonb_agg(jsonb_build_object('id',r.id,'name',r.setup_name,'class',r.race_class,
 'values',(select jsonb_object_agg(key,value) from jsonb_each(r.custom_fields#>'{onlyfast_setup_library_v1,values}') where value<>'""'::jsonb)) order by r.setup_name)
 from public.race_setups r where r.user_id=auth.uid() and r.setup_name like 'LIVE QA - % - 20261001')) as verification from onlyfast_live_qa_result;
commit;
